/**
 * Up to three suggestions under the composer, each one person's own: what
 * happened in their recent work, linked to where it happened, and the next step
 * as a prompt the composer takes.
 *
 * Nothing here is written by hand. The rows are generated by Hanzo's own model
 * (`MODEL`, POST /v1/chat/completions with the person's bearer, so the call is
 * theirs like any other) from that person's activity alone: their recent
 * conversations, their Dev runs, the org's issues and pull requests, their
 * automations and their files. An account with no activity yet is given rows
 * from what signup learned (its role, its use, what it said about its work),
 * until there is activity to read. No input and no answer is no row: the model
 * may answer none, and nothing pads it.
 *
 * Kept in the account (`suggest` in /v1/pref), so the rows follow the person:
 *
 *   {at, sig, rows, dismissed}   when they were made, the fingerprint of what
 *                                they were made from, the rows, and the rows
 *                                the person dismissed (by id)
 *
 * They are made again a day later, or once the activity's fingerprint has moved
 * and the rows are at least `QUIET` old, so a busy hour asks the model once.
 *
 * This file is the pure half: inputs to a request, an answer to validated rows,
 * the fingerprint and the policy. suggestions.tsx reads the sources and draws them.
 */
import type { Automation } from './api/auto.ts'
import type { Conversation } from './api/conversations.ts'
import type { Item } from './api/library.ts'
import type { Session } from './api/sessions.ts'
import type { Issue } from './merge.ts'

export type Icon = 'github' | 'agent' | 'chat' | 'file' | 'task'
export const ICONS: readonly Icon[] = ['github', 'agent', 'chat', 'file', 'task']

/** One row: where it came from, what happened, and what to do next. */
export interface Suggestion {
  /** Stable across generations: the source's address, or the title for a row with none. */
  id: string
  icon: Icon
  /** What happened, a few words: "Hanzo app login fixes landed". */
  title: string
  /** The source's own https address, copied from an input, or '' for none. */
  href: string
  /** What the source says, a sentence or three: the hover card. */
  summary: string
  /** The next step, a few words: "Verify the user flow". */
  action: string
  /** What the composer is given when the row is chosen. */
  prompt: string
}

/** One piece of the person's activity, as the model is shown it. */
export interface Input {
  kind: 'conversation' | 'issue' | 'pull' | 'run' | 'automation' | 'file'
  /** Its identity: an id, or its address. */
  key: string
  title: string
  /** open or closed, a run's status, an automation's last result. */
  state: string
  /** One line of detail: an issue's opening line, a run's repository, a schedule. */
  text: string
  /** Its own https address, or ''. */
  href: string
  /** RFC 3339, or ''. */
  updated: string
}

/** What signup and Settings learned about the person: the seed when there is no activity. */
export interface Seed {
  /** What Hanzo calls them. */
  name?: string
  /** What best describes their work (Settings). */
  work?: string
  /** The role chosen at signup (IAM `onboarding.role`). */
  role?: string
  /** personal, team or enterprise (IAM `onboarding.use`). */
  use?: string
  /** What every run is told about how they like to work. */
  instructions?: string
}

/** What the account keeps under `suggest`. */
export interface Kept {
  /** RFC 3339: when the rows were made. */
  at: string
  /** The fingerprint of the inputs they were made from. */
  sig: string
  rows: Suggestion[]
  /** Ids of the rows the person dismissed, newest first. */
  dismissed: string[]
}

/** Hanzo's model the rows are asked of: it decodes under a strict JSON schema at api.hanzo.ai. */
export const MODEL = 'zen5-flash'

/** At most this many rows. */
export const MOST = 3

const HOUR = 3_600_000
/** Rows this old are made again whatever happened. */
export const DAY = 24 * HOUR
/** Rows younger than this are kept even when the activity has moved. */
export const QUIET = HOUR

/** How many dismissals are remembered. */
export const REMEMBER = 100

/** How many of each source the model reads. */
export const TAKE: Record<Input['kind'], number> = { conversation: 8, issue: 6, pull: 4, run: 6, automation: 4, file: 4 }

const str = (v: unknown): string => (typeof v === 'string' ? v : '')
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : {})

/** One line, at most `n` characters. */
export function line(v: unknown, n: number): string {
  const s = str(v).replace(/\s+/g, ' ').trim()
  return s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s
}

/** An https address, or ''. A row links to nothing else. */
export function https(v: unknown): string {
  try {
    const u = new URL(str(v))
    return u.protocol === 'https:' ? u.href : ''
  } catch {
    return ''
  }
}

/** cyrb53: a 53-bit string hash, as 14 hex digits. A fingerprint, never a secret. */
export function hash(s: string): string {
  let h1 = 0xdeadbeef
  let h2 = 0x41c6ce57
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i)
    h1 = Math.imul(h1 ^ c, 2654435761)
    h2 = Math.imul(h2 ^ c, 1597334677)
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909)
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909)
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(14, '0')
}

const time = (iso: string): number => {
  const t = Date.parse(iso)
  return Number.isFinite(t) ? t : 0
}

/** What the sources answered, read by suggestions.tsx. */
export interface Activity {
  conversations: Conversation[]
  /** The org's issues and pull requests (GET /v1/task/board). */
  issues: Issue[]
  /** The org's Dev runs; only the person's own are read. */
  runs: Session[]
  automations: Automation[]
  /** The person's own Library items. */
  files: Item[]
  /** The person as a run's `actor` names them: `<owner>/<sub>`. */
  me: string
}

/** The first line of a text. */
const first = (s: string): string => s.split('\n').find((l) => l.trim()) ?? ''

/** The person's activity as inputs: their own runs only, each kind's newest `TAKE`. */
export function inputs(a: Activity): Input[] {
  const all: Input[] = [
    ...a.conversations.map((c) => ({ kind: 'conversation' as const, key: c.id, title: c.title, state: '', text: '', href: '', updated: c.updated })),
    ...a.issues.map((i) => ({
      kind: i.pull ? ('pull' as const) : ('issue' as const),
      key: i.key,
      title: i.title,
      state: i.state === 'closed' ? 'closed' : i.status || 'open',
      text: [i.repo || i.forge || i.board, first(i.body)].filter(Boolean).join(': '),
      href: https(i.url),
      updated: i.updated,
    })),
    ...a.runs
      .filter((r) => a.me && r.actor === a.me)
      .map((r) => ({
        kind: 'run' as const,
        key: r.id,
        title: r.title,
        state: r.status,
        text: [r.repo, r.branch].filter(Boolean).join(' @ '),
        href: https(r.pr),
        updated: r.updatedAt || r.createdAt,
      })),
    ...a.automations
      .filter((x) => !x.draft)
      .map((x) => ({
        kind: 'automation' as const,
        key: x.id,
        title: x.name,
        state: x.last?.status || (x.enabled ? 'on' : 'off'),
        text: x.last?.summary || first(x.instructions),
        href: '',
        updated: x.last?.at || x.updated,
      })),
    ...a.files.map((f) => ({ kind: 'file' as const, key: f.id, title: f.name, state: f.kind, text: f.source, href: '', updated: f.updated || f.created })),
  ]
  return pick(all)
}

/**
 * The seed: what the account's preferences say (`callName`, `work`,
 * `instructions` in /v1/pref) and what signup kept on the IAM user (`onboarding`
 * in /v1/iam/preferences: the role picked, and personal, team or enterprise).
 */
export function seed(p: { callName?: string; work?: string; instructions?: string }, iam: unknown): Seed {
  const o = obj(obj(iam).onboarding)
  const out: Seed = {
    name: line(p.callName, 60),
    work: line(p.work, 240),
    role: line(o.role, 80),
    use: line(o.use, 20),
    instructions: line(p.instructions, 400),
  }
  return Object.fromEntries(Object.entries(out).filter(([, v]) => v)) as Seed
}

/** Each kind's newest `TAKE`, newest first overall. */
export function pick(all: Input[]): Input[] {
  const out: Input[] = []
  for (const kind of Object.keys(TAKE) as Input['kind'][]) {
    out.push(
      ...all
        .filter((i) => i.kind === kind && i.title)
        .sort((a, b) => time(b.updated) - time(a.updated))
        .slice(0, TAKE[kind]),
    )
  }
  return out.sort((a, b) => time(b.updated) - time(a.updated))
}

/**
 * The fingerprint of what the rows are made from: each input's identity and
 * state, and the seed. A new conversation, a closed issue or a finished run
 * moves it; another turn in a conversation already read does not.
 */
export function sig(inputs: Input[], seed: Seed): string {
  const lines = inputs.map((i) => `${i.kind}\t${i.key}\t${i.state}`).sort()
  const s = [seed.name, seed.work, seed.role, seed.use, seed.instructions].map((x) => x ?? '').join('\t')
  return hash(`${lines.join('\n')}\n--\n${s}`)
}

/** Whether rows kept at `kept` are to be made again, now that the inputs read as `now`. */
export function due(kept: Kept | null, fingerprint: string, now: number): boolean {
  if (!kept) return true
  const age = now - time(kept.at)
  if (!time(kept.at) || age < 0 || age >= DAY) return true
  return kept.sig !== fingerprint && age >= QUIET
}

/** Whether anything newer could change kept rows yet: false while they are younger than `QUIET`. */
export function stale(kept: Kept | null, now: number): boolean {
  if (!kept) return true
  const age = now - time(kept.at)
  return !time(kept.at) || age < 0 || age >= QUIET
}

/** The icon a row about `i` carries: GitHub's mark only for GitHub's own address. */
export function iconOf(i: Input): Icon {
  switch (i.kind) {
    case 'conversation':
      return 'chat'
    case 'issue':
    case 'pull':
      return /^https:\/\/github\.com\//.test(i.href) ? 'github' : 'task'
    case 'run':
    case 'automation':
      return 'agent'
    case 'file':
      return 'file'
  }
}

/** The answer's shape, decoded strictly by the model. */
export const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['rows'],
  properties: {
    rows: {
      type: 'array',
      maxItems: MOST,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['icon', 'title', 'href', 'summary', 'action', 'prompt'],
        properties: {
          icon: { type: 'string', enum: [...ICONS] },
          title: { type: 'string' },
          href: { type: 'string' },
          summary: { type: 'string' },
          action: { type: 'string' },
          prompt: { type: 'string' },
        },
      },
    },
  },
} as const

const SYSTEM = [
  'You choose up to three next steps for one person, from their own recent activity, to show under the box where they type to Hanzo.',
  'Each row names something that happened and the step it calls for. Pick what is most worth their attention now: something that landed and needs checking, something open and urgent, something they were in the middle of.',
  'Fields:',
  '- title: what happened, at most 6 words, naming the thing ("Hanzo app login fixes landed", "Kai P0 mapping bug is open").',
  '- action: the next step, imperative, at most 6 words ("Verify the user flow").',
  '- summary: one to three plain sentences of what the source says. Only facts from the input; never invent numbers, names or dates.',
  '- prompt: the message the person would send Hanzo to do the step, first person, complete on its own, naming the source and its address when it has one.',
  '- href: copied exactly from the input the row is about, or "" when that input has none. Never write an address that is not in the input.',
  '- icon: github for a github.com address, agent for a run or an automation, chat for a conversation, file for a file, task for any other issue or task.',
  'Answer three rows. Take them from the activity first; fill the rest from what the person told us at signup (their role, their work): first things to ask Hanzo, with href "".',
  'Never repeat an item listed under skip. Never suggest the same item twice.',
  'With neither activity nor anything from signup worth a row, answer fewer; never pad with a weak one.',
].join('\n')

/** The chat completion that asks for rows, or null when there is nothing to make them from. */
export function request(inputs: Input[], seed: Seed, skip: string[], now: Date): Record<string, unknown> | null {
  const person = Object.fromEntries(Object.entries(seed).filter(([, v]) => typeof v === 'string' && v.trim()))
  if (!inputs.length && !Object.keys(person).length) return null
  const activity = inputs.map((i) => ({
    kind: i.kind,
    title: line(i.title, 140),
    ...(i.state ? { state: i.state } : {}),
    ...(i.text ? { text: line(i.text, 240) } : {}),
    href: i.href,
    ...(i.updated ? { updated: i.updated.slice(0, 10) } : {}),
  }))
  return {
    model: MODEL,
    messages: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: JSON.stringify({ today: now.toISOString().slice(0, 10), person, activity, skip }) },
    ],
    response_format: { type: 'json_schema', json_schema: { name: 'suggestions', strict: true, schema: SCHEMA } },
    max_tokens: 1200,
    temperature: 0.3,
  }
}

/** The first JSON object in a model's text: all of it, or from its first `{` to its last `}`. */
function json(text: string): unknown {
  try {
    return JSON.parse(text)
  } catch {
    const a = text.indexOf('{')
    const b = text.lastIndexOf('}')
    if (a < 0 || b <= a) return null
    try {
      return JSON.parse(text.slice(a, b + 1))
    } catch {
      return null
    }
  }
}

/** The text of a chat completion's first choice, or ''. */
export function content(raw: unknown): string {
  const choices = obj(raw).choices
  const first = obj(Array.isArray(choices) ? choices[0] : null)
  return str(obj(first.message).content)
}

/** A row's id: its address, or for a row without one, its title. */
export const idOf = (href: string, title: string): string => hash(href || title.toLowerCase())

/**
 * The rows of a chat completion, validated: each with every field, an address
 * that is one of the inputs' own (or none), its icon from that input, one row
 * per source, at most `MOST`. Anything else is dropped, never repaired.
 */
export function answer(raw: unknown, inputs: Input[]): Suggestion[] {
  const by = new Map(inputs.filter((i) => i.href).map((i) => [i.href, i]))
  const rows = obj(json(content(raw))).rows
  const out: Suggestion[] = []
  for (const r of Array.isArray(rows) ? rows : []) {
    const o = obj(r)
    const title = line(o.title, 80)
    const action = line(o.action, 80).replace(/\.$/, '')
    const prompt = str(o.prompt).trim().slice(0, 2000)
    if (!title || !action || !prompt) continue
    const said = str(o.href).trim()
    const source = said ? by.get(said) : undefined
    if (said && !source) continue
    // GitHub's mark only beside GitHub's own address: a row without one is a task at most.
    const named = ICONS.includes(o.icon as Icon) ? (o.icon as Icon) : 'chat'
    const icon = source ? iconOf(source) : named === 'github' ? 'task' : named
    const id = idOf(said, title)
    if (out.some((x) => x.id === id)) continue
    out.push({ id, icon, title: title.replace(/\.$/, ''), href: said, summary: line(o.summary, 600), action, prompt })
    if (out.length === MOST) break
  }
  return out
}

/** One kept row, or null for one that does not read as a row. */
function row(raw: unknown): Suggestion | null {
  const o = obj(raw)
  const title = str(o.title)
  const action = str(o.action)
  const prompt = str(o.prompt)
  const href = str(o.href)
  if (!title || !action || !prompt || (href && https(href) !== href)) return null
  return {
    id: str(o.id) || idOf(href, title),
    icon: ICONS.includes(o.icon as Icon) ? (o.icon as Icon) : 'chat',
    title,
    href,
    summary: str(o.summary),
    action,
    prompt,
  }
}

/** The `suggest` key of the preference document, or undefined when it holds none. */
export function kept(raw: unknown): Kept | undefined {
  const o = obj(raw)
  if (!Object.keys(o).length) return undefined
  return {
    at: str(o.at),
    sig: str(o.sig),
    rows: (Array.isArray(o.rows) ? o.rows : []).map(row).filter((r): r is Suggestion => r !== null).slice(0, MOST),
    dismissed: (Array.isArray(o.dismissed) ? o.dismissed : []).filter((x): x is string => typeof x === 'string' && x !== '').slice(0, REMEMBER),
  }
}

/** The rows to draw: those not dismissed. */
export const shown = (k: Kept | null | undefined): Suggestion[] => (k ? k.rows.filter((r) => !k.dismissed.includes(r.id)).slice(0, MOST) : [])

/** What Hanzo does, three ways in: what fills the rows a person's activity and signup do not. */
export const STARTERS: readonly Suggestion[] = [
  { id: 'start:chat', icon: 'chat', title: 'Think something through', href: '', summary: '', action: 'Ask Hanzo', prompt: 'Help me think through ' },
  { id: 'start:dev', icon: 'agent', title: 'Build an app or a site', href: '', summary: '', action: 'Describe it', prompt: 'Build me ' },
  { id: 'start:research', icon: 'file', title: 'Research a topic', href: '', summary: '', action: 'Get a cited brief', prompt: 'Research this and give me a short brief with sources: ' },
]

/** The kept rows, filled to `MOST` with the starters not dismissed: never one lonely row. */
export const fill = (k: Kept | null | undefined): Suggestion[] => {
  if (!k) return []
  const rows = shown(k)
  return [...rows, ...STARTERS.filter((r) => !k.dismissed.includes(r.id))].slice(0, Math.max(rows.length, MOST))
}

/** `k` with `id` dismissed: remembered first, the oldest forgotten past `REMEMBER`. */
export function dismissed(k: Kept, id: string): Kept {
  return { ...k, dismissed: [id, ...k.dismissed.filter((x) => x !== id)].slice(0, REMEMBER) }
}

/** The addresses and titles of dismissed rows the model is told to skip. */
export function skip(k: Kept | null | undefined, inputs: Input[]): string[] {
  if (!k) return []
  const gone = new Set(k.dismissed)
  const out = new Set<string>()
  for (const i of inputs) if (i.href && gone.has(idOf(i.href, ''))) out.add(i.href)
  for (const r of k.rows) if (gone.has(r.id)) out.add(r.href || r.title)
  return [...out]
}
